def check_stationarity_d(
    y: np.ndarray,
    max_d: int = 2,
    alpha: float = 0.05,
    test: str = "kpss",
) -> Tuple[int, List[Dict[str, Any]]]:
    """
    Determine the integration order d using repeated stationarity tests (Hyndman-Khandakar Step 1).

    Parameters
    ----------
    y : np.ndarray
        1D target time series array.
    max_d : int, default 2
        Maximum differencing order to consider.
    alpha : float, default 0.05
        Significance level for the stationarity hypothesis test.
    test : str, default 'kpss'
        Stationarity test to apply: 'kpss' (Kwiatkowski-Phillips-Schmidt-Shin) or 'adf' (Augmented Dickey-Fuller).

    Returns
    -------
    d : int
        The determined differencing order (0 <= d <= max_d).
    logs : list of dict
        Diagnostics and test statistics for each differencing iteration.
    """
    y_curr = np.asarray(y, dtype=np.float64)
    y_curr = y_curr[~np.isnan(y_curr)]
    if len(y_curr) < 4:
        return 0, [{"d": 0, "stat": np.nan, "pval": 1.0, "action": "too_short"}]

    d = 0
    logs = []
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        while d < max_d:
            # Check constant series
            if np.all(y_curr == y_curr[0]):
                logs.append({"d": d, "stat": 0.0, "pval": 1.0, "action": "constant_series"})
                break

            if test == "kpss":
                # Null hypothesis H0: Series is level stationary
                try:
                    stat, pval, _, _ = kpss(y_curr, regression="c", nlags="auto")
                    is_stationary = (pval >= alpha)
                except Exception as ex:
                    logs.append({"d": d, "stat": np.nan, "pval": np.nan, "action": f"kpss_error_{ex}"})
                    break
            elif test == "adf":
                # Null hypothesis H0: Series has unit root (non-stationary)
                try:
                    res = adfuller(y_curr)
                    stat, pval = res[0], res[1]
                    is_stationary = (pval < alpha)
                except Exception as ex:
                    logs.append({"d": d, "stat": np.nan, "pval": np.nan, "action": f"adf_error_{ex}"})
                    break
            else:
                raise ValueError(f"Unsupported stationarity test '{test}'. Use 'kpss' or 'adf'.")

            if is_stationary:
                logs.append({
                    "d": d,
                    "stat": float(stat),
                    "pval": float(pval),
                    "action": "stationary_stop"
                })
                break
            else:
                logs.append({
                    "d": d,
                    "stat": float(stat),
                    "pval": float(pval),
                    "action": "difference"
                })
                y_curr = np.diff(y_curr)
                d += 1

        if d == max_d and (len(logs) == 0 or logs[-1]["action"] == "difference"):
            # Max d reached
            try:
                if test == "kpss":
                    stat, pval, _, _ = kpss(y_curr, regression="c", nlags="auto")
                else:
                    res = adfuller(y_curr)
                    stat, pval = res[0], res[1]
            except Exception:
                stat, pval = np.nan, np.nan
            logs.append({
                "d": d,
                "stat": float(stat) if not np.isnan(stat) else np.nan,
                "pval": float(pval) if not np.isnan(pval) else np.nan,
                "action": "max_d_reached"
            })

    return d, logs


